ee:variables.ee:set-variable:
%dw 2.0
output application/json skipNullOn="everywhere"
var Body = vars.Body
var postingDate =
    if (Body.record_date != null)
        (Body.record_date as String splitBy " ")[0]
    else
        null
---

{
  "TransferHeader": {
    "Transfer_No": "",
    "Transfer_from_Code": Body.from_warehouse,
    "Transfer_to_Code": Body.to_warehouse,
    "Direct_Transfer": false,
    "EXT_Doc_Ref_No": Body.record_id as Number default "",
    "In_Transit_Code": "YR",//Lisa to confirm hard coding 
    "Posting_Date": postingDate,//Lisa to confirm mapping
    //"Shipment_Date":  postingDate,//Not Required to be auto populated by BC
    //"Receipt_Date":  postingDate,//Not Required to be auto populated by BC
    "Assigned_user": ""
    //"Shortcut_Dimension_1": "FOP.ADMIN",//Not Required to be auto populated by BC
    //"Shortcut_Dimension_2": ""//Not Required to be auto populated by BC
  },
  "TransferLine": Body.item_list map ((item, index) -> {
      "Item_No": item.item_code,
      "Quantity": item.item_quantity as Number,
      "Qty_to_Ship": item.item_quantity as Number
      //"Shipment_Date": postingDate,//Not Required to be auto populated by BC
      //"Receipt_Date": postingDate//Not Required to be auto populated by BC
    } )
}

%dw 2.0
output application/json
var value=  (if ( upper(vars.Body.transaction_type) == "ORDER" ) "2" else if ( upper(vars.Body.transaction_type) == "SALE" ) "1" else if ( upper(vars.Body.transaction_type) == "CREDIT NOTE" ) "5" else "")
var Body = vars.Body
var ts = vars.Body.tax_sync_time
var ts_formatted = (if (ts != null and ts != "")
  (ts as LocalDateTime {format: "yyyy-MM-dd HH:mm:ss"})
    as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
else
  ts)
---
//This is for sales with order(Converting sales orders to posted sales invoices)
if ( vars.request_endpoint== "Integration_PostSalesDocument" ) ({
	"Documents": [{
		"Document_No": Body.sales_order_erp_reference,
		"Document_Type": 2,
		"Ship": true,
		"Invoice": true,
		"TaxInvoiceNumber": Body.tax_invoice_number,
		"TaxVerificationCode": Body.tax_verification_code,
		"TaxReceiptNumber": Body.tax_receipt_number,
		"TaxQRCode": Body.tax_qr_code,
		"TaxSyncTime": ts_formatted,
		"TaxPrinter": Body.tax_printer,
		"TaxIdentificationNumber": Body.tax_identification_number,
		"Items": Body.item_list map ((item, index) ->
        {
			"No.": item.item_code,
			"QtyToShip": item.item_quantity,
			"QtyToInvoice": item.item_quantity
		})
	}]
})
//This is for orders and credit notes
else if ( vars.request_endpoint== "Integration_SalesDocument" )
({
	"SalesHeader": {
		"Invoice_No": "",
		"Customer_No": Body.customer_code,
		"Document_Type": value,
		"Currency_Code": "",
		//"Solutech_Ref_No": "",
		"Due_Date": (Body.expected_delivery_date splitBy  " ")[0],
		"Requested_Delivery_Date": (Body.expected_delivery_date splitBy  " ")[0],
		"Promised_Delivery_Date": (Body.expected_delivery_date splitBy  " ")[0],
		"External_Document_No": "",
		"Your_Reference": Body.lpo_number default "",
		"Salesperson_Code": Body.user_code,
		"Campaign_No": "",
		"Opportunity_No": "",
		"Responsibility_Center": "",
		"Assigned_User_ID": Body.user_name,
		"EXT_Doc_Ref_No": Body.record_id as Number default ""
	},
	"SalesLine": Body.item_list map ((item, index) ->
        {
		"Line_Type": 2,//1=G/L Account, 2=Item, 3=Resource
		"Item_No": item.item_code,
		"Quantity": item.item_quantity,
		"Unit_Price": item.item_price,
		"Discount_Percentage": item.discount_rate
		//"Gen_Prod_Posting_Group": "CONSUMABLES", //agreed with Lisa that the system will be auto populating it
		//"VAT_Prod_Posting_Group": "",//agreed with Lisa that the system will be auto populating it
		//"Gen_Bus_Posting_Group": "DOMESTIC"//agreed with Lisa that the system will be auto populating it
	})
})
//This is for direct sales(Van sales) creation of Invoice and direct posting 
else if ( vars.request_endpoint== "Integration_CreateAndPostSalesDocument" )
({
	"SalesHeader": {
		"Invoice_No": "",
		"Customer_No": Body.customer_code,
		"Document_Type": value,
		"Currency_Code": "",
		//"Solutech_Ref_No": "",
		//"Due_Date": (Body.expected_delivery_date splitBy  " ")[0],
		//"Requested_Delivery_Date": (Body.expected_delivery_date splitBy  " ")[0],
		//"Promised_Delivery_Date": "2026-02-12",
		"External_Document_No": Body.record_id as Number default "",
		"Your_Reference": "",
		"Salesperson_Code": Body.user_code,
		//"Campaign_No": "",
		//"Opportunity_No": "",
		//"Responsibility_Center": "",
		//"Assigned_User_ID": Body.user_name,
		"EXT_Doc_Ref_No": Body.record_id as Number default "",
		//"Invoice_ID": Body.tax_verification_code
		"TaxInvoiceNumber": Body.tax_invoice_number,
		"TaxVerificationCode": Body.tax_verification_code,
		"TaxReceiptNumber": Body.tax_receipt_number,
		"TaxQRCode": Body.tax_qr_code,
		"TaxSyncTime": ts_formatted,
		"TaxPrinter": Body.tax_printer,
		"TaxIdentificationNumber": Body.tax_identification_number default ""
	},
	"SalesLine": Body.item_list map ((item, index) ->
        {
		"Line_Type": 1,//1= Item, 2=G/L Account, 3=Resource,4=Fixed Asset
		"Item_No": item.item_code,
		"Quantity": item.item_quantity,
		"Unit_Price": item.item_price,
		"Discount_Percentage": item.discount_rate,
		"Unit_Of_Measure": item.uom_code,
		"Location_Code": item.store_code //confirmed by Lisa it is required 
		//"Gen_Prod_Posting_Group": "CONSUMABLES",
		//"VAT_Prod_Posting_Group": "",
		//"Gen_Bus_Posting_Group": "DOMESTIC"
	})
})
else 
({
	"SalesHeader": {
		"Invoice_No": Body.lpo_number default "",
		"Customer_No": Body.customer_code,
		"Document_Type": value,
		"Currency_Code": "",
		"Solutech_Ref_No": "",
		"Due_Date": (Body.expected_delivery_date splitBy  " ")[0],
		"Requested_Delivery_Date": (Body.expected_delivery_date splitBy  " ")[0],
		"Promised_Delivery_Date": (Body.expected_delivery_date splitBy  " ")[0],
		"External_Document_No": "",
		"Your_Reference": "",
		"Salesperson_Code": Body.user_code,
		"Campaign_No": "",
		"Opportunity_No": "",
		"Responsibility_Center": "",
		"Assigned_User_ID": Body.user_name,
		"EXT_Doc_Ref_No": Body.record_id as Number default ""
	},
	"SalesLine": Body.item_list map ((item, index) ->
        {
		"Line_Type": 2,
		"Item_No": item.item_code,
		"Quantity": item.item_quantity,
		"Unit_Price": item.item_price,
		"Discount_Percentage": item.discount_rate
		//"Gen_Prod_Posting_Group": "CONSUMABLES",
		//"VAT_Prod_Posting_Group": "",
		//"Gen_Bus_Posting_Group": "DOMESTIC"
	})
})

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"Message": "INVALID VALUE: Sale,Order & Credit Note not found as a Document Type"
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json

var Body = vars.Body

var paymentReference =
    Body.payment_reference default ""

var postingDate =
    (Body.record_date as LocalDateTime {
        format: "yyyy-MM-dd HH:mm:ss"
    }) as Date
    
// Map payment modes to their respective codes
/* {
    "Lines":
        if (!isEmpty(Body.invoices))
            Body.invoices map (invoice, index) -> {
                "InvoiceNo": invoice.record_id default "",
                "Amount": invoice.amount default Body.amount,
                "Description": (Body.user_code default "") ++ "-" ++ ((invoice.record_id default Body.record_id) as String),
                "PostingDate": postingDate,
                "Payment_Method": Body.payment_mode,
                "Payment_Reference": paymentReference,
                "CustNo": Body.customer_code,
		        "SalespersonCode": Body.user_code 
            }
        else
            [
                {
                    "InvoiceNo": "",
                    "Amount": Body.amount,
                    "Description": (Body.user_code default "") ++ "-" ++ ((Body.record_id default "") as String),
                    "PostingDate": postingDate,
                    "Payment_Method": Body.payment_mode,
                    "Payment_Reference": paymentReference,
                    "CustNo": Body.customer_code,
		            "SalespersonCode": Body.user_code  
                }
            ]
}
*/
---
{
    "Header": {
        "PaymentNo": (Body.record_id default "") as String,
        "CustNo": Body.customer_code default "",
        "Payment_Amount": Body.amount default 0,
        "Payment_Method": Body.payment_mode default "",
        "Payment_Reference": paymentReference,
        "PostingDate": postingDate,
        //"Description": (Body.user_code default "") ++ "-" ++ ((Body.record_id default "") as String),
        "Description": Body.user_code default "",
        "SalespersonCode": Body.user_code default ""
    },

    "Lines":
        if (!isEmpty(Body.invoices))
            Body.invoices map (invoice) -> {
                "InvoiceNo": invoice.erp_reference default "",
                "Amount_Allocated": invoice.amount default 0
            }
        else
            []
}
